// Generate a diverse Janet value x and call janet_checkint16(x).
// We ensure x is a valid Janet by constructing via public helpers.
Janet x;
unsigned int choice = *FUZZ_PARAM(unsigned int);
switch (choice % 6) {
    case 0: {
        double d = *FUZZ_PARAM(double);
        x = janet_wrap_number(d);
        break;
    }
    case 1: {
        int32_t i = *FUZZ_PARAM(int32_t);
        x = janet_wrap_integer(i);
        break;
    }
    case 2: {
        std::string s = FUZZ_PARAM_STR();
        int32_t len = (int32_t)((s.size() > 128) ? 128 : s.size());
        JanetString js = janet_string((const uint8_t *)s.data(), len);
        x = janet_wrap_string(js);
        break;
    }
    case 3: {
        int32_t cap = (int32_t)(*FUZZ_PARAM(unsigned int) % 4);
        JanetArray *arr = janet_array(cap);
        for (int i = 0; i < cap; i++) {
            janet_array_push(arr, janet_wrap_integer((int32_t)i));
        }
        x = janet_wrap_array(arr);
        break;
    }
    case 4: {
        x = janet_wrap_nil();
        break;
    }
    default: {
        int b = (*FUZZ_PARAM(int)) & 1;
        x = janet_wrap_boolean(b);
        break;
    }
}
volatile int res = janet_checkint16(x);
(void)res; // Property: function must accept any Janet; result is advisory.
// Validation: We constructed x via safe wrappers; no undefined behavior paths are taken.

