# This generator produces interesting arbitrary binary strings (bytes) intended to
# seed FUZZ_PARAM_STR and FUZZ_PARAM_FILENAME in the provided stubs. The stubs
# consume these as generic byte payloads for Janet string/symbol/keyword creation,
# parser input, numeric scanners, and formatting/testing functions.
#
# Strategy:
# - Compose a byte string by concatenating several segments chosen from a palette
#   that targets different code paths: numeric literals, keywords/symbolic tokens,
#   Janet syntax snippets, long repeats, high-bit bytes, NULs, and varying lengths.
# - Include both ASCII-printable and arbitrary binary data, with optional NULs
#   inside to exercise C-string-limited paths vs. explicit-length APIs.
# - Keep the result <= 4096 bytes.

ASCII_NUMS = [
    b"0", b"-0", b"1", b"-1", b"42", b"-42", b"2147483647", b"-2147483648",
    b"4294967295", b"-9223372036854775808", b"9223372036854775807",
    b"0x0", b"0xff", b"0x7fffffff", b"0xffffffff", b"0b101010", b"0777",
    b"1e0", b"-1e0", b"3.141592653589793", b"1e309", b"-1e309", b"NaN", b"inf", b"-inf"
]

JANET_SNIPPETS = [
    b"",  # empty
    b"nil", b"true", b"false",
    b"(def x 123)", b"[1 2 3]", b"{\"a\" 1 :b 2}", b"(:keyword 10)",
    b"(+ 1 2)", b"(do (print \"hi\") 5)", b"(array 1 2 3)", b"(tuple 1 2)",
    b"(struct :a 1 :b 2)", b"(defn f [x] (+ x 1))", b"; comment line\n",
]

SYMBOL_LIKE = [
    b"sym", b"kw", b":kw", b"with-dash", b"snake_case", b"UPPER", b"mix3d",
    b"space name", b"unicode-\xe2\x98\x83", b"contains\x00nul",
]

DELIMS = [b"\n", b" ", b"\t", b",", b";", b"\r\n"]

# Random high-entropy binary blocks including NULs

def rand_binary(rng: random.Random, max_len: int) -> bytes:
    n = rng.randint(0, max_len)
    # Bias to include some NULs and high-bit bytes
    out = bytearray()
    for _ in range(n):
        choice = rng.random()
        if choice < 0.15:
            out.append(0)
        elif choice < 0.35:
            out.append(rng.randint(128, 255))
        else:
            out.append(rng.randint(1, 127))
    return bytes(out)


def repeated_block(rng: random.Random) -> bytes:
    # Create a small token and repeat it to create length diversity
    token_choices = [b"a", b"0", b" ", b"\n", b"\t", b"x", b"\\", b"\x00", b"_", b"-"]
    token = rng.choice(token_choices)
    reps = rng.randint(1, 256)
    return token * reps


def numeric_mixture(rng: random.Random) -> bytes:
    parts: List[bytes] = []
    k = rng.randint(1, 4)
    for _ in range(k):
        parts.append(rng.choice(ASCII_NUMS))
        parts.append(rng.choice(DELIMS))
    return b"".join(parts)


def janet_code_mixture(rng: random.Random) -> bytes:
    parts: List[bytes] = []
    k = rng.randint(1, 4)
    for _ in range(k):
        parts.append(rng.choice(JANET_SNIPPETS))
        parts.append(rng.choice(DELIMS))
    return b"".join(parts)


def symbol_keywords(rng: random.Random) -> bytes:
    parts: List[bytes] = []
    k = rng.randint(1, 5)
    for _ in range(k):
        parts.append(rng.choice(SYMBOL_LIKE))
        parts.append(rng.choice(DELIMS))
    return b"".join(parts)


def with_embedded_nuls(rng: random.Random, base: bytes) -> bytes:
    if not base:
        return b"\x00"
    ba = bytearray(base)
    # Insert a few NULs at random positions
    for _ in range(rng.randint(1, 4)):
        pos = rng.randint(0, len(ba))
        ba[pos:pos] = b"\x00"
    return bytes(ba)


def size_biased_chunk(rng: random.Random) -> bytes:
    # Mix chunk sizes: tiny, medium, large (but cap total later)
    p = rng.random()
    if p < 0.3:
        return rand_binary(rng, 8)
    elif p < 0.8:
        return rand_binary(rng, 128)
    else:
        return rand_binary(rng, 1024)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    segments: List[bytes] = []

    # Start with a BOM or UTF marker sometimes to exercise Unicode paths
    if rng.random() < 0.3:
        segments.append(rng.choice([b"\xef\xbb\xbf", b"\xff\xfe", b"\xfe\xff"]))

    # Include numeric literals for scan_number/_int64/_uint64
    if rng.random() < 0.9:
        segments.append(numeric_mixture(rng))

    # Include plausible Janet code for parser and dobytes/dostring
    if rng.random() < 0.9:
        segments.append(janet_code_mixture(rng))

    # Include symbol/keyword-like tokens
    if rng.random() < 0.9:
        segments.append(symbol_keywords(rng))

    # Add a repeated block to vary lengths and trigger buffer growth paths
    if rng.random() < 0.8:
        segments.append(repeated_block(rng))

    # Add some raw binary including high-bit and NULs
    if rng.random() < 0.95:
        segments.append(size_biased_chunk(rng))

    # Occasionally embed extra NULs to influence cstring-based calls
    if rng.random() < 0.5 and segments:
        idx = rng.randrange(len(segments))
        segments[idx] = with_embedded_nuls(rng, segments[idx])

    # Add delimiters and small tokens to separate sections
    for _ in range(rng.randint(1, 5)):
        segments.append(rng.choice(DELIMS))
        # Small chance to append a small ASCII identifier
        if rng.random() < 0.5:
            segments.append(rng.choice(SYMBOL_LIKE))

    # Final random binary tail
    if rng.random() < 0.7:
        segments.append(rand_binary(rng, 256))

    data = b"".join(segments)

    # Ensure size limit <= 4096 bytes
    if len(data) > 4096:
        data = data[:4096]

    return data
